// Blocky character built from box primitives + canvas textures.
// Used in-game, in studio presence and in the avatar editor preview.
import * as THREE from 'three';
import { drawFace } from '../avatar2d.js';

function mat(color) {
  return new THREE.MeshStandardMaterial({ color: new THREE.Color(color), roughness: 0.75 });
}

function box(w, h, d, material) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
  m.castShadow = true;
  return m;
}

function faceTexture(faceKind) {
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  drawFace(c.getContext('2d'), 128, 128, faceKind);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function buildHat(mesh) {
  const g = new THREE.Group();
  const color = new THREE.Color(mesh.color || '#888888');
  const m = new THREE.MeshStandardMaterial({ color, roughness: 0.5 });
  switch (mesh.kind) {
    case 'cone': {
      const cone = new THREE.Mesh(new THREE.ConeGeometry(0.55, 1.1, 16), m);
      cone.position.y = 0.55;
      g.add(cone);
      break;
    }
    case 'torus': {
      const t = new THREE.Mesh(new THREE.TorusGeometry(0.5, 0.09, 10, 24), new THREE.MeshStandardMaterial({ color, emissive: 0x806000, roughness: 0.25, metalness: 0.6 }));
      t.rotation.x = Math.PI / 2;
      t.position.y = 0.45;
      g.add(t);
      break;
    }
    case 'tophat': {
      const brim = new THREE.Mesh(new THREE.CylinderGeometry(0.72, 0.72, 0.08, 18), m);
      const top = new THREE.Mesh(new THREE.CylinderGeometry(0.45, 0.45, 0.85, 18), m);
      top.position.y = 0.45;
      g.add(brim, top);
      break;
    }
    case 'crown': {
      const base = new THREE.Mesh(new THREE.CylinderGeometry(0.5, 0.55, 0.3, 8), new THREE.MeshStandardMaterial({ color, metalness: 0.8, roughness: 0.25 }));
      base.position.y = 0.18;
      g.add(base);
      for (let i = 0; i < 5; i++) {
        const spike = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.3, 4), base.material);
        const a = (i / 5) * Math.PI * 2;
        spike.position.set(Math.cos(a) * 0.45, 0.45, Math.sin(a) * 0.45);
        g.add(spike);
      }
      break;
    }
    case 'antenna': {
      const rod = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.04, 0.7, 8), mat('#777788'));
      rod.position.y = 0.35;
      const orb = new THREE.Mesh(new THREE.SphereGeometry(0.14, 12, 10), new THREE.MeshStandardMaterial({ color, emissive: color.clone().multiplyScalar(0.5), roughness: 0.3 }));
      orb.position.y = 0.75;
      g.add(rod, orb);
      break;
    }
    case 'cap': {
      const dome = new THREE.Mesh(new THREE.SphereGeometry(0.55, 16, 10, 0, Math.PI * 2, 0, Math.PI / 2), m);
      dome.scale.y = 0.7;
      const bill = new THREE.Mesh(new THREE.BoxGeometry(0.65, 0.07, 0.45), m);
      bill.position.set(0, 0.05, 0.62);
      g.add(dome, bill);
      break;
    }
    case 'viking': {
      const dome = new THREE.Mesh(new THREE.SphereGeometry(0.58, 16, 10, 0, Math.PI * 2, 0, Math.PI / 2), new THREE.MeshStandardMaterial({ color, metalness: 0.7, roughness: 0.35 }));
      g.add(dome);
      for (const side of [-1, 1]) {
        const horn = new THREE.Mesh(new THREE.ConeGeometry(0.13, 0.55, 8), mat('#e8dcc8'));
        horn.position.set(side * 0.55, 0.3, 0);
        horn.rotation.z = -side * 0.9;
        g.add(horn);
      }
      break;
    }
    case 'propeller': {
      const beanie = new THREE.Mesh(new THREE.SphereGeometry(0.55, 16, 10, 0, Math.PI * 2, 0, Math.PI / 2), m);
      beanie.scale.y = 0.65;
      const stick = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 0.25, 6), mat('#cccccc'));
      stick.position.y = 0.42;
      const prop = new THREE.Mesh(new THREE.BoxGeometry(1.0, 0.04, 0.12), mat('#ffd23f'));
      prop.position.y = 0.55;
      prop.name = 'spin';
      g.add(beanie, stick, prop);
      break;
    }
  }
  return g;
}

function nameSprite(username, color = '#ffffff') {
  const c = document.createElement('canvas');
  c.width = 512; c.height = 128;
  const ctx = c.getContext('2d');
  ctx.font = 'bold 56px "Segoe UI", sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.shadowColor = 'rgba(0,0,0,0.8)';
  ctx.shadowBlur = 10;
  ctx.fillStyle = color;
  ctx.fillText(username, 256, 64);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, depthTest: false }));
  sprite.scale.set(4, 1, 1);
  return sprite;
}

function bubbleSprite(text) {
  const c = document.createElement('canvas');
  c.width = 512; c.height = 128;
  const ctx = c.getContext('2d');
  ctx.font = '600 40px "Segoe UI", sans-serif';
  const tw = Math.min(480, ctx.measureText(text).width + 40);
  ctx.fillStyle = 'rgba(255,255,255,0.95)';
  ctx.beginPath();
  ctx.roundRect(256 - tw / 2, 24, tw, 80, 18);
  ctx.fill();
  ctx.fillStyle = '#16323f';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  let t = text;
  while (ctx.measureText(t).width > 440 && t.length > 2) t = t.slice(0, -2);
  if (t !== text) t += '…';
  ctx.fillText(t, 256, 64);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, depthTest: false }));
  sprite.scale.set(5, 1.25, 1);
  return sprite;
}

// Character is ~3 units tall to match PLAYER half-height 1.5.
export class Character {
  constructor(avatar, username, catalog) {
    avatar = avatar || {};
    const bc = avatar.bodyColors || {};
    this.group = new THREE.Group();

    const torsoM = mat(bc.torso || '#2a7de1');
    const headM = mat(bc.head || '#ffd23f');

    this.torso = box(1.2, 1.2, 0.6, torsoM);
    this.torso.position.y = 0.0;

    // head with face decal on +Z
    const headMats = [headM, headM, headM, headM, headM, headM];
    const faceKind = String(avatar.face || 'face_smile').replace('face_', '');
    const faceTex = faceTexture(faceKind);
    headMats[4] = new THREE.MeshStandardMaterial({
      color: headM.color, roughness: 0.75, map: faceTex,
    });
    this.head = new THREE.Mesh(new THREE.BoxGeometry(0.85, 0.85, 0.85), headMats);
    this.head.castShadow = true;
    this.head.position.y = 1.1;

    this.armL = box(0.45, 1.15, 0.45, mat(bc.leftArm || '#ffd23f'));
    this.armR = box(0.45, 1.15, 0.45, mat(bc.rightArm || '#ffd23f'));
    this.armL.position.set(-0.85, 0.0, 0);
    this.armR.position.set(0.85, 0.0, 0);
    // pivot at shoulder
    this.armL.geometry.translate(0, -0.45, 0); this.armL.position.y += 0.45;
    this.armR.geometry.translate(0, -0.45, 0); this.armR.position.y += 0.45;

    this.legL = box(0.5, 1.2, 0.5, mat(bc.leftLeg || '#37474f'));
    this.legR = box(0.5, 1.2, 0.5, mat(bc.rightLeg || '#37474f'));
    this.legL.position.set(-0.32, -1.2, 0);
    this.legR.position.set(0.32, -1.2, 0);
    this.legL.geometry.translate(0, -0.5, 0); this.legL.position.y += 0.5;
    this.legR.geometry.translate(0, -0.5, 0); this.legR.position.y += 0.5;

    this.group.add(this.torso, this.head, this.armL, this.armR, this.legL, this.legR);

    // hat
    if (avatar.hat && catalog) {
      const item = catalog.find((i) => i.id === avatar.hat);
      if (item && item.mesh) {
        this.hat = buildHat(item.mesh);
        this.hat.position.y = 1.52;
        this.group.add(this.hat);
      }
    }

    if (username) {
      this.tag = nameSprite(username);
      this.tag.position.y = 2.45;
      this.group.add(this.tag);
    }

    // "it" indicator for tag mode (hidden by default)
    this.itMarker = new THREE.Mesh(
      new THREE.ConeGeometry(0.3, 0.55, 4),
      new THREE.MeshStandardMaterial({ color: 0xff3030, emissive: 0x661010 })
    );
    this.itMarker.rotation.x = Math.PI;
    this.itMarker.position.y = 2.0;
    this.itMarker.visible = false;
    this.group.add(this.itMarker);

    this._walkT = 0;
    this._bubbleTimer = null;
  }

  setIt(on) {
    this.itMarker.visible = on;
  }

  say(text) {
    if (this.bubble) { this.group.remove(this.bubble); this.bubble = null; }
    this.bubble = bubbleSprite(text);
    this.bubble.position.y = 3.1;
    this.group.add(this.bubble);
    clearTimeout(this._bubbleTimer);
    this._bubbleTimer = setTimeout(() => {
      if (this.bubble) { this.group.remove(this.bubble); this.bubble = null; }
    }, 4500);
  }

  // anim: 'idle' | 'walk' | 'jump'
  animate(dt, anim, speed = 1) {
    if (anim === 'walk') {
      this._walkT += dt * 9 * speed;
      const s = Math.sin(this._walkT);
      this.armL.rotation.x = s * 0.9;
      this.armR.rotation.x = -s * 0.9;
      this.legL.rotation.x = -s * 0.75;
      this.legR.rotation.x = s * 0.75;
    } else if (anim === 'jump') {
      this.armL.rotation.x += (-2.6 - this.armL.rotation.x) * 0.2;
      this.armR.rotation.x += (-2.6 - this.armR.rotation.x) * 0.2;
      this.legL.rotation.x += (0.4 - this.legL.rotation.x) * 0.2;
      this.legR.rotation.x += (-0.3 - this.legR.rotation.x) * 0.2;
    } else {
      this._walkT = 0;
      for (const limb of [this.armL, this.armR, this.legL, this.legR]) {
        limb.rotation.x *= 0.8;
      }
      // gentle idle sway
      const t = performance.now() / 1000;
      this.armL.rotation.z = Math.sin(t * 1.4) * 0.04;
      this.armR.rotation.z = -Math.sin(t * 1.4) * 0.04;
    }
    if (this.hat) {
      const prop = this.hat.getObjectByName('spin');
      if (prop) prop.rotation.y += dt * 10;
    }
  }

  dispose() {
    this.group.removeFromParent();
  }
}
